def missingTerm(nums):
    n = len(nums)
    first = nums[0]
    d = (nums[-1] - first) // n
    lo, hi = 1, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] == first + mid * d:
            lo = mid + 1
        else:
            hi = mid
    return first + lo * d
